def _pair(v):
    if isinstance(v, tuple):
        return v
    return (v, v)


class ModelNew(nn.Module):
    """
    2D transposed convolution implemented with a single cooperative tiled
    CUTE/CUDA kernel (gather formulation with shared-memory weight staging).
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1), padding: tuple = (0, 0),
                 dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        kernel_size = _pair(kernel_size)
        stride = _pair(stride)
        padding = _pair(padding)
        dilation = _pair(dilation)

        assert in_channels % groups == 0
        assert out_channels % groups == 0

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = int(groups)

        kh, kw = kernel_size
        # Match PyTorch ConvTranspose2d weight layout: [Cin, Cout/groups, KH, KW]
        self.weight = nn.Parameter(
            torch.empty(self.in_channels, self.out_channels // self.groups, kh, kw))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv_transpose2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = init._calculate_fan_in_and_fan_out(self.weight)
            if fan_in != 0:
                bound = 1 / math.sqrt(fan_in)
                init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv_transpose2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride[0]), int(self.stride[1]),
            int(self.padding[0]), int(self.padding[1]),
            int(self.dilation[0]), int(self.dilation[1]),
            int(self.groups),
        )

